NODE, EDGE, ATTR = range(3)


class Node:
    def __init__(self, name, attrs):
        self.name = name
        self.attrs = attrs

    def __eq__(self, other):
        # Ensure comparison is only with other Node objects.
        if not isinstance(other, Node):
            return NotImplemented
        return self.name == other.name and self.attrs == other.attrs

    # __hash__ is required for Node objects to be stored in sets (for uniqueness checking).
    # Dictionaries are mutable and thus unhashable.
    # To make 'attrs' hashable, we convert its items to a frozenset.
    def __hash__(self):
        return hash((self.name, frozenset(self.attrs.items())))


class Edge:
    def __init__(self, src, dst, attrs):
        self.src = src
        self.dst = dst
        self.attrs = attrs

    def __eq__(self, other):
        # Ensure comparison is only with other Edge objects.
        if not isinstance(other, Edge):
            return NotImplemented
        return (self.src == other.src and
                self.dst == other.dst and
                self.attrs == other.attrs)

    # __hash__ is required for Edge objects to be stored in sets (for uniqueness checking).
    # Dictionaries are mutable and thus unhashable.
    # To make 'attrs' hashable, we convert its items to a frozenset.
    def __hash__(self):
        return hash((self.src, self.dst, frozenset(self.attrs.items())))


