        # Internal sets for efficient uniqueness checks of nodes and edges.
        self._nodes_unique = set()
        self._edges_unique = set()

        # Public lists to store nodes and edges.
        # Tests expect these to be lists and to maintain insertion order
        # for unique items, or at least be comparable as lists.
        self.nodes = []
        self.edges = []
        self.attrs = {}

        # Validate the top-level 'data' structure.
        # It must be a list and contain at least one tuple.
        # This covers cases like Graph() (data=None) and Graph([]) (empty list).
        if not isinstance(data, list) or not data:
            raise TypeError("Graph data malformed")

        for item in data:
            # Each item in 'data' must be a non-empty tuple.
            if not isinstance(item, tuple) or not item:
                raise TypeError("Graph data malformed")

            item_type = item[0]  # The first element indicates the type (ATTR, NODE, EDGE)

            if item_type == ATTR:
                # Expected format: (ATTR, key_str, value_str)
                if len(item) != 3:
                    raise ValueError("ATTRIBUTE malformed")
                key, value = item[1], item[2]
                if not isinstance(key, str) or not isinstance(value, str):
