                # Expected format: (EDGE, src_name_str, dst_name_str, attrs_dict)
                if len(item) != 4:
                    raise ValueError("EDGE malformed")
                src_name, dst_name, edge_attrs = item[1], item[2], item[3]
                if not (isinstance(src_name, str) and
